    (hab : a ⨯₃ b ≠ 0) (hac : a ⨯₃ c ≠ 0) (hbc : b ⨯₃ c ≠ 0)
    (qa : evalC q a = 0) (qb : evalC q b = 0) (qc : evalC q c = 0) :
